insert into public.sat_question_bank(id,practice_test_id,subject,module,question_number,source_page,answer_page,correct_answer,accepted_answers,response_type,question_lines,explanation_lines,needs_visual,content_status,question_mode) values
('practice-test-8:rw2-1','practice-test-8','english','rw2',1,1,1,'A','["A"]'::jsonb,'multiple-choice','["The pilot project was considered _______ because its results could be applied to a much larger network.","A) scalable","B) obsolete","C) arbitrary","D) irrelevant"]'::jsonb,'["Scalable means able to be extended to a larger operation."]'::jsonb,false,'verified','text'),
('practice-test-8:rw2-2','practice-test-8','english','rw2',2,1,1,'B','["B"]'::jsonb,'multiple-choice','["The researcher was _______ about the cause because several variables changed at once.","A) certain","B) cautious","C) dogmatic","D) dismissive"]'::jsonb,'["Cautious matches the inability to isolate a single cause."]'::jsonb,false,'verified','text'),
('practice-test-8:rw2-3','practice-test-8','english','rw2',3,1,1,'C','["C"]'::jsonb,'multiple-choice','["The proposal''s benefits were _______ by the unusually high maintenance costs.","A) enhanced","B) confirmed","C) offset","D) ignored"]'::jsonb,'["Offset means counterbalanced by another factor."]'::jsonb,false,'verified','text'),
('practice-test-8:rw2-4','practice-test-8','english','rw2',4,1,1,'B','["B"]'::jsonb,'multiple-choice','["Her interpretation was _______ with the observations: it accounted for every recorded measurement.","A) inconsistent","B) compatible","C) irrelevant","D) unfounded"]'::jsonb,'["Compatible means consistent with the observations."]'::jsonb,false,'verified','text'),
('practice-test-8:rw2-5','practice-test-8','english','rw2',5,1,1,'B','["B"]'::jsonb,'multiple-choice','["Select the correctly punctuated sentence.","A) The storm ended, crews began repairs.","B) The storm ended; crews began repairs.","C) The storm ended; and crews began repairs.","D) The storm ended crews began repairs."]'::jsonb,'["The semicolon joins two independent clauses."]'::jsonb,false,'verified','text'),
('practice-test-8:rw2-6','practice-test-8','english','rw2',6,1,1,'B','["B"]'::jsonb,'multiple-choice','["Choose the correct transition punctuation.","A) The trial succeeded, therefore, the design was adopted.","B) The trial succeeded; therefore, the design was adopted.","C) The trial succeeded; therefore the design was adopted.","D) The trial succeeded therefore; the design was adopted."]'::jsonb,'["Use a semicolon before therefore and comma after it."]'::jsonb,false,'verified','text'),
('practice-test-8:rw2-7','practice-test-8','english','rw2',7,1,1,'A','["A"]'::jsonb,'multiple-choice','["Which sentence correctly introduces an example?","A) The report describes one concern: the bridge''s drainage system.","B) The report describes: one concern the bridge''s drainage system.","C) The report: describes one concern the bridge''s drainage system.","D) The report describes one: concern, the bridge''s drainage system."]'::jsonb,'["A colon follows the complete independent clause and introduces its elaboration."]'::jsonb,false,'verified','text'),
('practice-test-8:rw2-8','practice-test-8','english','rw2',8,1,1,'B','["B"]'::jsonb,'multiple-choice','["Which sentence is a complete sentence without an unnecessary semicolon?","A) Although the test ended; the team stayed.","B) Although the test ended, the team stayed.","C) Although the test ended the team stayed;","D) Although; the test ended, the team stayed."]'::jsonb,'["The dependent clause is followed by a comma before the independent clause."]'::jsonb,false,'verified','text'),
('practice-test-8:rw2-9','practice-test-8','english','rw2',9,1,1,'B','["B"]'::jsonb,'multiple-choice','["Solar output in kilowatt-hours: January 120, February 165, March 150. Which month increased by 45 from January?","A) January","B) February","C) March","D) None"]'::jsonb,'["165−120=45 kWh."]'::jsonb,false,'verified','text'),
('practice-test-8:rw2-10','practice-test-8','english','rw2',10,1,1,'C','["C"]'::jsonb,'multiple-choice','["At Center A, 72 of 80 deliveries were on time; at Center B, 81 of 90 were on time. Which has a higher rate?","A) Center A","B) Center B","C) They are equal","D) Not enough data"]'::jsonb,'["72/80 and 81/90 are both 90%."]'::jsonb,false,'verified','text'),
('practice-test-8:rw2-11','practice-test-8','english','rw2',11,1,1,'B','["B"]'::jsonb,'multiple-choice','["Average wait times fell from 15 to 12 minutes at Site X and from 20 to 14 minutes at Site Y. Which had the larger reduction?","A) Site X, by 3 minutes","B) Site Y, by 3 minutes","C) Site X, by 6 minutes","D) Both fell equally"]'::jsonb,'["X fell 3 and Y fell 6 minutes, so Y''s reduction was 3 greater."]'::jsonb,false,'verified','text'),
('practice-test-8:rw2-12','practice-test-8','english','rw2',12,1,1,'A','["A"]'::jsonb,'multiple-choice','["A survey surveyed 40 walkers and 60 cyclists. Of them, 30 walkers and 30 cyclists favored a change. Which group had the higher support percentage?","A) Walkers","B) Cyclists","C) Both equal","D) Not enough data"]'::jsonb,'["30/40=75% while 30/60=50%."]'::jsonb,false,'verified','text'),
('practice-test-8:rw2-13','practice-test-8','english','rw2',13,1,1,'A','["A"]'::jsonb,'multiple-choice','["A study finds that people using the new park also report better sleep, but no sleep data were collected before the park opened. What is a limitation?","A) The study cannot compare sleep before and after opening.","B) Sleep data can never be measured.","C) Park visitors did not report their sleep.","D) Every visitor sleeps equally."]'::jsonb,'["Without baseline sleep data, improvement cannot be established."]'::jsonb,false,'verified','text'),
('practice-test-8:rw2-14','practice-test-8','english','rw2',14,1,1,'A','["A"]'::jsonb,'multiple-choice','["A school hopes replacing noisy fans will improve concentration. Which comparison would provide the strongest evidence?","A) Measure concentration before and after replacement, with an otherwise similar classroom as a comparison.","B) Ask which fan color students prefer.","C) Count the fans in the building.","D) Assume quieter fans improve all scores."]'::jsonb,'["A before-and-after comparison with a comparison group addresses the proposed effect."]'::jsonb,false,'verified','text'),
('practice-test-8:rw2-15','practice-test-8','english','rw2',15,1,1,'A','["A"]'::jsonb,'multiple-choice','["A report says trees reduce street temperature because shaded streets were cooler, but shaded streets also had less traffic. What remains uncertain?","A) Whether reduced traffic contributes to the observed temperature difference","B) Whether the streets had trees","C) Whether the streets had temperatures","D) Whether some streets were shaded"]'::jsonb,'["Traffic differences are an alternative explanation that was not controlled."]'::jsonb,false,'verified','text'),
('practice-test-8:rw2-16','practice-test-8','english','rw2',16,1,1,'A','["A"]'::jsonb,'multiple-choice','["A trial records a 10% faster delivery time after a software update. Which claim is justified?","A) The measured deliveries were faster after the update.","B) The update will improve every delivery everywhere.","C) The update alone caused all improvements.","D) No delivery was slower after the update."]'::jsonb,'["The measured average improvement does not establish universality or causality."]'::jsonb,false,'verified','text'),
('practice-test-8:math2-1','practice-test-8','math','math2',1,1,1,'B','["B"]'::jsonb,'multiple-choice','["For $x>0$, simplify $x^{5/2}/x^{1/2}$.","A) $x$","B) $x^2$","C) $x^3$","D) $x^5$"]'::jsonb,'["Subtract exponents: 5/2−1/2=2."]'::jsonb,false,'verified','text'),
('practice-test-8:math2-2','practice-test-8','math','math2',2,1,1,'B','["B"]'::jsonb,'multiple-choice','["If $3^{x+2}=81$, what is $x$?","A) 1","B) 2","C) 3","D) 4"]'::jsonb,'["81=3^4, so x+2=4."]'::jsonb,false,'verified','text'),
('practice-test-8:math2-3','practice-test-8','math','math2',3,1,1,'B','["B"]'::jsonb,'multiple-choice','["Simplify $\\sqrt{72}$.","A) $3\\sqrt8$","B) $6\\sqrt2$","C) $12\\sqrt2$","D) $8\\sqrt3$"]'::jsonb,'["72=36×2, so √72=6√2."]'::jsonb,false,'verified','text'),
('practice-test-8:math2-4','practice-test-8','math','math2',4,1,1,'B','["B"]'::jsonb,'multiple-choice','["If $\\sqrt{2x+9}=5$, what is $x$?","A) 6","B) 8","C) 10","D) 12"]'::jsonb,'["2x+9=25, so x=8."]'::jsonb,false,'verified','text'),
('practice-test-8:math2-5','practice-test-8','math','math2',5,1,1,'B','["B"]'::jsonb,'multiple-choice','["Corresponding angles measure $(5x+1)°$ and $(3x+29)°$ across parallel lines. Find $x$.","A) 12","B) 14","C) 16","D) 28"]'::jsonb,'["Corresponding angles are equal: 5x+1=3x+29, x=14."]'::jsonb,false,'verified','text'),
('practice-test-8:math2-6','practice-test-8','math','math2',6,1,1,'C','["C"]'::jsonb,'multiple-choice','["An angle measures 52°. What is the supplementary angle?","A) 38°","B) 52°","C) 128°","D) 142°"]'::jsonb,'["A linear pair sums to 180°, so 180−52=128°."]'::jsonb,false,'verified','text'),
('practice-test-8:math2-7','practice-test-8','math','math2',7,1,1,'C','["C"]'::jsonb,'multiple-choice','["Alternate interior angles for two parallel lines are $(7x−5)°$ and $(4x+31)°$. Find $x$.","A) 10","B) 11","C) 12","D) 13"]'::jsonb,'["Set the angles equal: 7x−5=4x+31, x=12."]'::jsonb,false,'verified','text'),
('practice-test-8:math2-8','practice-test-8','math','math2',8,1,1,'B','["B"]'::jsonb,'multiple-choice','["Same-side interior angles are 104° and $y°$. Find $y$.","A) 66°","B) 76°","C) 86°","D) 104°"]'::jsonb,'["Same-side interior angles are supplementary, so 180−104=76°."]'::jsonb,false,'verified','text'),
('practice-test-8:math2-9','practice-test-8','math','math2',9,1,1,'C','["C"]'::jsonb,'multiple-choice','["For what $k$ do $x+2y=5$ and $2x+ky=13$ have no solution?","A) 2","B) 3","C) 4","D) 5"]'::jsonb,'["Coefficients are proportional when k=4, but constants 5 and 13 do not scale."]'::jsonb,false,'verified','text'),
('practice-test-8:math2-10','practice-test-8','math','math2',10,1,1,'C','["C"]'::jsonb,'multiple-choice','["The line $y=ax−4$ passes through (3,11). Find $a$.","A) 3","B) 4","C) 5","D) 7"]'::jsonb,'["11=3a−4 gives 3a=15, a=5."]'::jsonb,false,'verified','text'),
('practice-test-8:math2-11','practice-test-8','math','math2',11,1,1,'C','["C"]'::jsonb,'multiple-choice','["For which $b$ do $4x+by=12$ and $2x+3y=6$ have infinitely many solutions?","A) 3","B) 4","C) 6","D) 12"]'::jsonb,'["The first must be twice the second, so b=6."]'::jsonb,false,'verified','text'),
('practice-test-8:math2-12','practice-test-8','math','math2',12,1,1,'B','["B"]'::jsonb,'multiple-choice','["For $y=x^2+px+25$, the graph touches the x-axis at one point. If $p>0$, find $p$.","A) 5","B) 10","C) 20","D) 25"]'::jsonb,'["The discriminant p²−100=0 gives p=10."]'::jsonb,false,'verified','text'),
('practice-test-8:math2-13','practice-test-8','math','math2',13,1,1,'B','["B"]'::jsonb,'multiple-choice','["Find the center of $(x+6)^2+(y−2)^2=49$.","A) (6,−2)","B) (−6,2)","C) (6,2)","D) (−6,−2)"]'::jsonb,'["Standard form shows center (−6,2)."]'::jsonb,false,'verified','text'),
('practice-test-8:math2-14','practice-test-8','math','math2',14,1,1,'B','["B"]'::jsonb,'multiple-choice','["A radius from (0,0) to (5,12) has length?","A) 12","B) 13","C) 17","D) 169"]'::jsonb,'["Length √(25+144)=13."]'::jsonb,false,'verified','text'),
('practice-test-8:math2-15','practice-test-8','math','math2',15,1,1,'B','["B"]'::jsonb,'multiple-choice','["A circle''s diameter is 14. What is its circumference?","A) $7\\pi$","B) $14\\pi$","C) $49\\pi$","D) $196\\pi$"]'::jsonb,'["Circumference π times diameter gives 14π."]'::jsonb,false,'verified','text'),
('practice-test-8:math2-16','practice-test-8','math','math2',16,1,1,'B','["B"]'::jsonb,'multiple-choice','["A circle with center (−2,3) and radius 4 has which equation?","A) $(x−2)^2+(y+3)^2=16$","B) $(x+2)^2+(y−3)^2=16$","C) $(x+2)^2+(y−3)^2=4$","D) $(x−2)^2+(y−3)^2=16$"]'::jsonb,'["Standard form centers at (−2,3) and uses radius squared 16."]'::jsonb,false,'verified','text') on conflict(id) do nothing;
